<script lang="ts">
 import {onMount} from 'svelte';
 import {lessons as originalLessons,sources} from '$lib/lessons';
 import {contexts,chapterOrder,chapterNames,chapterGoals} from '$lib/lesson-context';
 import {focusedQuestions} from '$lib/interview-expansion';
 import {deepening,deepeningSource} from '$lib/practical-deepening';
 import {backtonyDeepening,backtonySource} from '$lib/backtony-deepening';
 import ConceptAnimation from '$lib/components/ConceptAnimation.svelte';
 import './study.css';
 const lessons=[...originalLessons].sort((a,b)=>chapterOrder.indexOf(a.category)-chapterOrder.indexOf(b.category));
 type RecordData={completed:string[];bookmarks:string[];notes:Record<string,string>;attempts:Record<string,number>;review:Record<string,number>;lastLesson?:string;updatedAt?:number};
 let record=$state<RecordData>({completed:[],bookmarks:[],notes:{},attempts:{},review:{}});
 let current=$state('process'),view=$state('course'),query=$state(''),filter=$state('all'),mobileNav=$state(false),status=$state('');
 let chosen=$state<number|null>(null),submitted=$state(false),interviewAnswer=$state(''),showAnswer=$state(false),step=$state(0),client=$state(0);
 let ready=false;let clock=$state(Date.now());
 const lesson=$derived(lessons.find(l=>l.id===current)!);
 const context=$derived(contexts[current]);
 const extra=$derived(deepening[current]||backtonyDeepening[current]);
 const extraSource=$derived(deepening[current]?deepeningSource:backtonySource);
 const extraUrl=$derived(extra?(deepening[current]?deepeningSource.url+'/blob/main/questions/'+extra.path+'.md':backtonySource.url+'/blob/master/'+extra.path):'');
 const index=$derived(lessons.findIndex(l=>l.id===current));
 const chapter=$derived(chapterOrder.indexOf(lesson.category));
 const due=$derived(lessons.filter(l=>(record.review[l.id]||Infinity)<=clock));
 const visible=$derived(lessons.filter(l=>(l.title+' '+l.definition+' '+l.english).toLowerCase().includes(query.toLowerCase())&&(filter==='all'||filter==='saved'&&record.bookmarks.includes(l.id)||filter==='review'&&due.some(d=>d.id===l.id))));
 const pythonCode=$derived(context.python||(lesson.language.startsWith('Python')?lesson.code:''));
 const interviewPrompt=$derived(focusedQuestions[current]);
 const nextUnread=$derived(lessons.find(l=>!record.completed.includes(l.id))||lessons[0]);
 function paragraphs(text:string){const sentences=text.split(/(?<=[.!?])\s+/);const parts:string[]=[];for(let i=0;i<sentences.length;i+=2)parts.push(sentences.slice(i,i+2).join(' '));return parts;}
 function save(){record.lastLesson=current;record.updatedAt=Date.now();if(ready)try{localStorage.setItem('serverNotebook.v1',JSON.stringify(record));}catch{status='기록을 저장하지 못했습니다. 브라우저 저장 공간을 확인하세요.';}}
 function route(){const p=new URL(location.href).searchParams;const id=p.get('lesson');if(id&&lessons.some(l=>l.id===id)){current=id;view='lesson';}else view=p.get('view')==='sources'?'sources':'course';filter=['saved','review'].includes(p.get('filter')||'')?p.get('filter')!:'all';}
 function select(id:string){current=id;view='lesson';chosen=null;submitted=false;interviewAnswer='';showAnswer=false;step=0;mobileNav=false;const u=new URL(location.href);u.search='';u.searchParams.set('lesson',id);history.pushState({},'',u);save();window.scrollTo({top:0,behavior:'instant'});}
 function course(){view='course';mobileNav=false;filter='all';query='';const u=new URL(location.href);u.search='';history.pushState({},'',u);window.scrollTo({top:0,behavior:'instant'});}
 function toggle(kind:'completed'|'bookmarks'){record[kind]=record[kind].includes(current)?record[kind].filter(id=>id!==current):[...record[kind],current];if(kind==='completed'&&record.completed.includes(current))record.review[current]=Date.now()+86400000;save();}
 function grade(){if(chosen===null)return;submitted=true;record.attempts[current]=(record.attempts[current]||0)+1;record.review[current]=chosen===lesson.quiz.correct?Date.now()+86400000:Date.now();clock=Date.now();save();}
 async function copyCode(){try{await navigator.clipboard.writeText(pythonCode);status='Python 예제를 복사했습니다.';}catch{status='코드 영역을 선택해 복사하세요.';}}
 onMount(()=>{try{const r=JSON.parse(localStorage.getItem('serverNotebook.v1')||'{}');record={completed:Array.isArray(r.completed)?r.completed.filter((id:string)=>lessons.some(l=>l.id===id)):[],bookmarks:Array.isArray(r.bookmarks)?r.bookmarks:[],notes:r.notes&&typeof r.notes==='object'?r.notes:{},attempts:r.attempts&&typeof r.attempts==='object'?r.attempts:{},review:r.review&&typeof r.review==='object'?r.review:{},lastLesson:lessons.some(l=>l.id===r.lastLesson)?r.lastLesson:undefined,updatedAt:r.updatedAt};if(lessons.some(l=>l.id===r.lastLesson))current=r.lastLesson;ready=true;}catch{status='저장한 기록을 읽지 못했습니다.';}route();if(view==='lesson')save();const pop=()=>{route();chosen=null;submitted=false;interviewAnswer='';showAnswer=false;mobileNav=false;step=0;};window.addEventListener('popstate',pop);const timer=setInterval(()=>clock=Date.now(),60000);return()=>{clearInterval(timer);window.removeEventListener('popstate',pop);};});
</script>
<svelte:head><title>{view==='lesson'?lesson.title:'백엔드·CS 학습 과정'} · CS 노트</title><meta name="description" content="컴퓨터 실행부터 네트워크·서버·데이터·클라우드까지. 필요한 이유와 역할을 이해하고 Python 예제로 확인하는 32개 단원."/></svelte:head>
<div class="study-book">
 <header class="book-header"><a href="/" class="book-brand">CS 노트</a><nav aria-label="학습 분야"><a href="/">학습 홈</a><button class:active={view!=='sources'} onclick={course}>백엔드·CS</button><a href="/practice">Python 코딩 실전</a></nav><button class="book-menu" aria-expanded={mobileNav} onclick={()=>mobileNav=!mobileNav}>목차 {mobileNav?'닫기':'열기'}</button></header>
 <div class="book-layout">
  <aside class="book-sidebar" class:open={mobileNav} aria-label="학습 목차">
   <button class="course-link" onclick={course}>← 전체 학습 순서</button><div class="book-progress"><strong>{record.completed.length} / 32</strong><span>단원 학습 완료</span><progress value={record.completed.length} max="32" aria-label="백엔드 학습 진도"></progress></div>
   <label class="book-search">단원 찾기<input aria-label="단원 검색" bind:value={query} placeholder="프로세스, NAT, 캐시…"/></label><details class="book-tools"><summary>북마크·복습</summary><div><button onclick={()=>filter='all'}>전체</button><button onclick={()=>filter='saved'}>북마크 {record.bookmarks.length}</button><button onclick={()=>filter='review'}>복습 {due.length}</button></div><p>현재: {filter==='all'?'전체':filter==='saved'?'북마크':'복습'}</p></details>
   <nav aria-label="순서대로 배우기">{#each chapterOrder as category,ci}{#if visible.some(l=>l.category===category)}<details class="book-chapter" open={view==='lesson'&&lesson.category===category||query.length>0||filter!=='all'}><summary>{chapterNames[ci]}</summary>{#each visible.filter(l=>l.category===category) as item}<button class:active={current===item.id&&view==='lesson'} aria-current={current===item.id&&view==='lesson'?'page':undefined} onclick={()=>select(item.id)}><span>{String(lessons.findIndex(l=>l.id===item.id)+1).padStart(2,'0')}</span><span>{item.title}</span>{#if record.completed.includes(item.id)}<span aria-label="학습 완료">✓</span>{/if}</button>{/each}</details>{/if}{/each}{#if !visible.length}<p>해당하는 단원이 없습니다.</p>{/if}</nav><small>진도와 메모는 이 브라우저에 저장됩니다.</small>
  </aside>
  <main class="book-main">
   {#if view==='course'}
    <section class="course-heading"><span>백엔드·CS · Python 예제 · 32단원</span><h1>기초부터 순서대로 배우기</h1><p>컴퓨터가 프로그램을 실행하는 원리부터, 요청이 서버와 데이터를 거쳐 클라우드에서 운영되는 과정까지 연결합니다.</p><div class="course-start"><button class="book-primary" onclick={()=>select(nextUnread.id)}>{record.completed.length?'다음 미완료 단원 읽기':'첫 단원 시작하기'} →</button>{#if record.lastLesson}<button onclick={()=>select(record.lastLesson!)}>마지막 단원 이어 읽기</button>{/if}</div></section>
    <div class="course-outline">{#each chapterOrder as category,ci}<section><div class="chapter-heading"><span>{String(ci+1).padStart(2,'0')}</span><div><h2>{chapterNames[ci].slice(3)}</h2><p>{chapterGoals[ci]}</p></div></div><ol>{#each visible.filter(l=>l.category===category) as item}<li><button onclick={()=>select(item.id)}><span class="unit-number">{String(lessons.findIndex(l=>l.id===item.id)+1).padStart(2,'0')}</span><span><strong>{item.title}</strong><small>{item.hook}</small></span><span>{record.completed.includes(item.id)?'✓':'→'}</span></button></li>{/each}</ol></section>{/each}</div>
   {:else if view==='sources'}
    <h1>참고 자료</h1><p>공통 CS 이론과 Python 실습을 공식 문서로 확인합니다.</p><p>질문 주제 보완에 <a href={deepeningSource.url} target="_blank" rel="noreferrer">{deepeningSource.name}</a>를 참고했습니다. 해당 보충 설명·예제는 <a href={deepeningSource.license} target="_blank" rel="noreferrer">CC BY-SA 4.0</a>입니다.</p><p>추가 주제 선정에 <a href={backtonySource.url} target="_blank" rel="noreferrer">{backtonySource.name}</a>도 참고했습니다. Java·Spring 전용 문법을 수록하지 않고 공통 CS 원리를 Python 사례로 작성했습니다.</p><div class="book-references">{#each Object.values(sources) as source}<a href={source.url} target="_blank" rel="noreferrer">{source.name} ↗</a>{/each}</div>
   {:else}
    <header class="reading-heading"><span>{chapterNames[chapter]} · 단원 {index+1}/32</span><h1>{lesson.title}</h1><p>{lesson.hook}</p><button class="book-bookmark" aria-pressed={record.bookmarks.includes(current)} onclick={()=>toggle('bookmarks')}>{record.bookmarks.includes(current)?'★ 북마크됨':'☆ 북마크'}</button></header>
    <nav class="reading-contents" aria-label="이 글의 목차"><strong>이 글의 목차</strong><a href="#definition">01. 정의와 비유</a><a href="#why">02. 필요한 이유</a><a href="#roles">03. 역할과 동작</a><a href="#examples">04. 실무 사례</a><a href="#python">05. Python 실습</a><a href="#review">06. 복습과 면접</a></nav>
    <article class="reading-page">
     <section id="definition"><div class="reading-label">01 · 무엇인가</div><h2>먼저, 정확한 정의</h2><p class="term-name">{lesson.english}</p>{#each paragraphs(lesson.definition) as paragraph}<p>{paragraph}</p>{/each}<div class="story-box"><h3>생활 속 장면으로 생각하기</h3>{#each paragraphs(lesson.analogy) as paragraph}<p>{paragraph}</p>{/each}</div></section>
     <section id="why"><div class="reading-label">02 · 왜 필요한가</div><h2>이렇게 나눈 이유</h2>{#each paragraphs(context.why) as paragraph}<p>{paragraph}</p>{/each}<h3>문제에서 설계로</h3>{#each paragraphs(context.background) as paragraph}<p>{paragraph}</p>{/each}</section>
     <section id="roles"><div class="reading-label">03 · 역할과 동작</div><h2>누가 무엇을 담당할까?</h2><div class="role-table"><table><thead><tr><th>구성 요소</th><th>책임과 역할</th></tr></thead><tbody>{#each context.roles as [name,role]}<tr><th scope="row">{name}</th><td>{role}</td></tr>{/each}</tbody></table></div><h3>실제로 움직이는 순서</h3>{#key current}<ConceptAnimation id={current}/>{/key}<ol class="reading-steps">{#each lesson.steps as action}<li>{action}</li>{/each}</ol>{#if current==='process'}<div class="story-box"><h3>프로세스와 스레드의 선택</h3><p>프로세스는 일반 메모리를 분리해 장애와 자원의 경계를 만들기 좋지만 시작·통신·메모리 비용을 고려해야 합니다. 스레드는 같은 프로세스의 자원을 공유해 협력이 쉽지만 공유 상태에 경쟁이 생겨 동기화가 필요합니다.</p><p>동시성은 여러 작업의 진행을 겹쳐 관리하는 것, 병렬성은 여러 작업이 실제로 같은 시간에 실행되는 것입니다. CPU 코어·런타임·작업 종류에 따라 결과가 달라집니다.</p></div>{/if}</section>
     <section id="examples"><div class="reading-label">04 · 작은 사례로 연결하기</div><h2>같은 문제, 다른 설계</h2><h3>분리하지 않았을 때</h3>{#each paragraphs(context.before) as paragraph}<p>{paragraph}</p>{/each}<h3>역할을 나누면</h3>{#each paragraphs(context.after) as paragraph}<p>{paragraph}</p>{/each}<details class="reading-more"><summary>다른 실무 사례와 AWS·Ncloud 적용</summary><h3>실무 사례</h3>{#each paragraphs(lesson.scenario) as paragraph}<p>{paragraph}</p>{/each}<h3>AWS에 배치한다면</h3>{#each paragraphs(lesson.aws) as paragraph}<p>{paragraph}</p>{/each}<h3>Ncloud에 배치한다면</h3>{#each paragraphs(lesson.ncloud) as paragraph}<p>{paragraph}</p>{/each}</details>{#if extra}<div class="practical-case"><h3>{extra.title}</h3>{#each paragraphs(extra.definition) as paragraph}<p>{paragraph}</p>{/each}<h4>이 구분이 필요한 이유</h4>{#each paragraphs(extra.why) as paragraph}<p>{paragraph}</p>{/each}<h4>실제 서버에서 만나는 장면</h4>{#each paragraphs(extra.scene) as paragraph}<p>{paragraph}</p>{/each}<ol class="reading-steps">{#each extra.steps as action}<li>{action}</li>{/each}</ol><div class="design-note"><strong>단정하면 틀리는 설명</strong>{#each paragraphs(extra.mistake) as paragraph}<p>{paragraph}</p>{/each}</div><p class="execution-note">주제 참고·재구성: <a href={extraUrl} target="_blank" rel="noreferrer">{extraSource.name}</a> · {#if deepening[current]}원문에서 선택한 주제를 Python 사례와 구현별 조건으로 보완했습니다. 이 보충 설명·예제는 <a href={deepeningSource.license} target="_blank" rel="noreferrer">CC BY-SA 4.0</a>으로 제공합니다.{:else}질문 주제를 확인하고 공식 문서에 근거해 설명·비유·Python 예제를 별도로 작성했습니다.{/if}</p></div>{/if}<div class="design-note"><h3>선택에는 비용이 있습니다</h3>{#each paragraphs(lesson.tradeoff) as paragraph}<p>{paragraph}</p>{/each}</div></section>
     <section id="python"><div class="reading-label">05 · Python으로 확인하기</div><h2>예측하고, 실행하고, 설명하기</h2><p>먼저 결과를 예상해 보세요. 실행 후 어떤 값이 바뀌었고 어떤 역할이 분리됐는지 앞의 설명에 연결합니다.</p><div class="reading-code"><div><strong>Python</strong><button onclick={copyCode}>코드 복사</button></div><pre><code>{pythonCode}</code></pre></div>{#if context.output}<h3>예상 결과와 관찰할 것</h3><p>{context.output}</p>{/if}{#if context.note}<div class="design-note"><h3>실행 환경과 Python에서의 주의점</h3>{#each paragraphs(context.note) as paragraph}<p>{paragraph}</p>{/each}</div>{:else}<p class="execution-note">PC의 Python에서 실행하는 예제입니다. 네트워크·파일·OS 상태에 의존하는 예제는 환경에 따라 결과가 달라집니다. 모형이라고 표시한 코드는 실제 서버나 클라우드를 조작하지 않습니다.</p>{/if}<ul>{#each lesson.codeNotes as note}<li>{note}</li>{/each}</ul>{#if !lesson.language.startsWith('Python')}<details class="reading-more"><summary>실무 구성도 살펴보기 · {lesson.language}</summary><pre><code>{lesson.code}</code></pre><p>Python 예제는 개념 모형이고 이 구성은 DB·서버·클라우드의 작업 형태입니다.</p></details>{/if}
      {#if extra}<h3>한 번 더 실험하기 · {extra.title.split(' · ')[0]}</h3><div class="reading-code"><div><strong>Python · 결과 검증 포함</strong></div><pre><code>{extra.code}</code></pre></div><h3>예상 결과</h3><pre class="expected-output"><code>{extra.output}</code></pre><p class="execution-note">{extra.note}</p>{/if}

     </section>
     <section id="review"><div class="reading-label">06 · 이해를 확인하기</div><h2>이제 내 말로 설명하기</h2><div class="memory-line"><strong>기억할 한 줄</strong><p>{lesson.memory}</p></div><p><strong>흔한 오해</strong> · {lesson.mistake}</p><h3>{interviewPrompt?.question||lesson.title+'의 정의, 필요한 이유와 실제 사용 예를 설명해 주세요.'}</h3><p>정의 → 필요한 이유 → 역할과 동작 → Python·실무 예 → 한계 순서로 설명해 보세요.</p><label class="book-field">내 설명<textarea aria-label="면접 답변 연습" bind:value={interviewAnswer} rows="5" placeholder="답을 읽기 전에 기억에서 적어 보세요."></textarea></label><button aria-expanded={showAnswer} onclick={()=>showAnswer=!showAnswer}>{showAnswer?'답변 예시 접기':'답변 예시와 비교하기'}</button>{#if showAnswer}<div class="story-box"><p>{lesson.answer}</p>{#if interviewPrompt}<p><strong>질문 의도</strong> · {interviewPrompt.intent}</p><ol>{#each interviewPrompt.outline as point}<li>{point}</li>{/each}</ol>{/if}<p>서술형 답변은 자동 채점하지 않습니다.</p><p class="execution-note">질문 주제 참고: <a href="https://github.com/ksundong/backend-interview-question" target="_blank" rel="noreferrer">ksundong/backend-interview-question</a> · 설명과 예시는 학습용으로 작성했습니다.</p></div>{/if}{#if extra}<details class="reading-more"><summary>실무 상황으로 답해 보기 · 추가 질문</summary><h3>{extra.question}</h3><p>먼저 원인, 선택 기준, 실패할 때의 처리 순서로 설명해 보세요.</p><details><summary>답변과 비교하기</summary>{#each paragraphs(extra.answer) as paragraph}<p>{paragraph}</p>{/each}</details></details>{/if}<details class="reading-more"><summary>한 단계 더 생각할 질문</summary>{#each lesson.follow as [q,a]}<h3>{q}</h3><p>{a}</p>{/each}</details><div class="reading-quiz"><h3>{lesson.quiz.question}</h3><div>{#each lesson.quiz.options as option,i}<button class:chosen={chosen===i} class:correct={submitted&&i===lesson.quiz.correct} disabled={submitted} aria-pressed={chosen===i} onclick={()=>chosen=i}>{String.fromCharCode(65+i)} · {option}</button>{/each}</div>{#if submitted}<p role="status"><strong>{chosen===lesson.quiz.correct?'정답입니다.':'다시 확인해 보세요.'}</strong> {lesson.quiz.explanation}</p><button onclick={()=>{chosen=null;submitted=false;}}>다시 풀기</button>{:else}<button class="book-primary" disabled={chosen===null} onclick={grade}>정답 확인</button>{/if}</div><label class="book-field">나중에 다시 볼 메모<textarea aria-label="단원 개인 노트" value={record.notes[current]||''} oninput={(e)=>{record.notes[current]=e.currentTarget.value;save();}} rows="4" placeholder="헷갈린 이유, 내 비유, 다시 확인할 점을 적으세요."></textarea></label></section>
    </article>
    <details class="unit-references"><summary>이 단원의 공식 참고 자료</summary>{#each lesson.refs as ref}<a href={sources[ref].url} target="_blank" rel="noreferrer">{sources[ref].name} ↗</a>{/each}{#if extra}{#each extra.refs as [name,url]}<a href={url} target="_blank" rel="noreferrer">{name} ↗</a>{/each}<a href={extraUrl} target="_blank" rel="noreferrer">면접 질문 주제 참고 · {extra.title.split(' · ')[0]} ↗</a>{/if}</details><div class="book-completion"><p>왜 필요한지와 동작을 내 말로 설명할 수 있으면 완료하세요.</p><button class="book-primary" aria-pressed={record.completed.includes(current)} onclick={()=>toggle('completed')}>{record.completed.includes(current)?'✓ 학습 완료 · 취소':'이 단원 학습 완료'}</button></div><nav class="book-pager" aria-label="단원 이동"><button disabled={index===0} onclick={()=>select(lessons[index-1].id)}>← 이전 단원<span>{index>0?lessons[index-1].title:'첫 단원'}</span></button><button onclick={course}>전체 목차</button><button disabled={index===lessons.length-1} onclick={()=>select(lessons[index+1].id)}>다음 단원 →<span>{index<lessons.length-1?lessons[index+1].title:'과정 마지막'}</span></button></nav>
   {/if}
   <footer class="book-footer"><span>CS 노트 · 백엔드·CS</span><button onclick={()=>{view='sources';window.scrollTo({top:0,behavior:'instant'});}}>전체 참고 자료</button></footer>
  </main>
 </div>
 {#if status}<div class="book-status" role="status">{status}<button aria-label="안내 닫기" onclick={()=>status=''}>×</button></div>{/if}
</div>
